CREATE TABLE IF NOT EXISTS tsmc_verifications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    material_no TEXT,
    tank_no TEXT,
    batch_no TEXT,
    supplier TEXT,
    original_location TEXT,
    target_location TEXT,
    raw_qr TEXT,
    status TEXT,
    photo_batch_url TEXT,
    photo_loc_url TEXT,
    source_order TEXT,
    doc_order TEXT
);
CREATE INDEX IF NOT EXISTS idx_tsmc_verif_created_at ON tsmc_verifications(created_at);
CREATE INDEX IF NOT EXISTS idx_tsmc_verif_batch_no ON tsmc_verifications(batch_no);
